<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\MessageContentVO;

trait MessageContentAttributeHolder
{
    protected MessageContentVO|string|null $content = null;
    protected bool $contentAssigned = false;

    public function getContentOrDefault(MessageContentVO $content): MessageContentVO
    {
        if ($this->contentAssigned) {
            \assert(null !== $this->content);
            return MessageContentVO::from($this->content);
        } else {
            return $content;
        }
    }
    public function content(MessageContentVO|string $content): static
    {
        $this->content = $content;
        $this->contentAssigned = true;
        return $this;
    }
    public function getContent(): ?string
    {
        return $this->content instanceof MessageContentVO ? $this->content->value() : $this->content;
    }
    public function isContentAssigned(): bool
    {
        return $this->contentAssigned;
    }
    public function writeContentTo(mixed $att): void
    {
        if ($this->contentAssigned) {
            \assert(null !== $this->content);
            $att->content($this->content);
        }
    }
    public function readContentFrom(mixed $att): void
    {
        if ($att->isContentAssigned()) {
            $content = $att->getContent();
            \assert(null !== $content);
            $this->content($content);
        }
    }
    public function unsetContent(): static
    {
        $this->contentAssigned = false;
        return $this;
    }
    protected function withDefaultContent(): void
    {
    }
    protected function withAssertedContentRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->contentAssigned = $this->contentAssigned) {
            $value->content = MessageContentVO::tryFrom($this->content, $errorsList);
        }
    }
}
